using System;using System.IO;using System.Globalization;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace IslandIntegrated {
 // Consumes only an explicitly published sanitized receipt. No environment,
 // account configuration, credentials, HTTP, controller pipe or shell access.
 public sealed class BalanceReadonlySnapshot {
  public string State="not-connected",Currency="";public DateTimeOffset ObservedAt;public decimal? Total,Granted,Topped;public bool Available;
  public bool Fresh(DateTimeOffset now){return State=="fresh"&&(now-ObservedAt).TotalSeconds>=-5&&(now-ObservedAt).TotalSeconds<=300;}
  public string Label(DateTimeOffset now){return Fresh(now)?(Currency=="CNY"?"\u00a5":"$")+Total.Value.ToString("0.00",CultureInfo.InvariantCulture):"\u2014";}
  static string S(IDictionary<string,object>d,string key){object o;return d.TryGetValue(key,out o)&&o is string?(string)o:"";}
  static decimal? Money(IDictionary<string,object>d,string key){decimal n;return Decimal.TryParse(S(d,key),NumberStyles.AllowDecimalPoint|NumberStyles.AllowLeadingSign,CultureInfo.InvariantCulture,out n)&&n>=-1000000000000m&&n<=1000000000000m?(decimal?)n:null;}
  public static BalanceReadonlySnapshot Parse(string raw){var invalid=new BalanceReadonlySnapshot{State="invalid"};try{if(raw==null||raw.Length>16384)return invalid;var d=new JavaScriptSerializer{MaxJsonLength=16384,RecursionLimit=4}.DeserializeObject(raw) as IDictionary<string,object>;if(d==null)return invalid;var allowed=new HashSet<string>(new[]{"schema","state","observedUtc","currency","total","granted","topped","available"});foreach(var key in d.Keys)if(!allowed.Contains(key))return invalid;if(S(d,"schema")!="sidebar.balance.v1")return invalid;string state=S(d,"state");if(state!="fresh")return new BalanceReadonlySnapshot{State=state=="unauthorized"||state=="access-denied"||state=="server-error"||state=="not-connected"?state:"invalid"};string stamp=S(d,"observedUtc");DateTimeOffset at;object available;if(!(stamp.EndsWith("Z",StringComparison.Ordinal)||System.Text.RegularExpressions.Regex.IsMatch(stamp,@"[+-]\d\d:\d\d$"))||!DateTimeOffset.TryParse(stamp,CultureInfo.InvariantCulture,DateTimeStyles.None,out at)||!d.TryGetValue("available",out available)||!(available is bool))return invalid;var result=new BalanceReadonlySnapshot{State="fresh",ObservedAt=at,Currency=S(d,"currency"),Total=Money(d,"total"),Granted=Money(d,"granted"),Topped=Money(d,"topped"),Available=(bool)available};return (result.Currency=="USD"||result.Currency=="CNY")&&result.Total.HasValue&&result.Granted.HasValue&&result.Topped.HasValue?result:invalid;}catch{return invalid;}}
  public static BalanceReadonlySnapshot Load(string file){try{var f=new FileInfo(file);if(!f.Exists)return new BalanceReadonlySnapshot();for(var p=f.Directory;p!=null;p=p.Parent)if(p.Exists&&(p.Attributes&FileAttributes.ReparsePoint)!=0)return new BalanceReadonlySnapshot{State="invalid"};if(f.Length>16384||(f.Attributes&FileAttributes.ReparsePoint)!=0)return new BalanceReadonlySnapshot{State="invalid"};return Parse(File.ReadAllText(file));}catch(UnauthorizedAccessException){return new BalanceReadonlySnapshot{State="access-denied"};}catch{return new BalanceReadonlySnapshot{State="invalid"};}}
 }
}
